26	ReduceOp::ReduceOp(Array<PrimExpr> args, BufferMap vmap) {
27	  src = vmap[GetVarFromAccessPtr(args[0])];
28	  dst = vmap[GetVarFromAccessPtr(args[1])];
29	  String reduce_type = args[2].as<StringImm>().value()->value;
30	  dim = args[3].as<IntImm>().value()->value;
31	  if (reduce_type == "sum")
32	    type = ReduceType::kSum;
33	  else if (reduce_type == "abssum")
34	    type = ReduceType::kAbsSum;
35	  else if (reduce_type == "absmax")
36	    type = ReduceType::kAbsMax;
37	  else if (reduce_type == "max")
38	    type = ReduceType::kMax;
39	  else if (reduce_type == "min")
40	    type = ReduceType::kMin;
41	  else
42	    ICHECK(0) << "Unknown reduce type: " << reduce_type;
43	  clear = args[4].as<Bool>().value();
44	}
45	
46	PrimExpr ReduceOp::MakeInitValue() const {
47	  switch (type) {
48	  case ReduceType::kSum:
49	    return make_zero(dst->dtype);
50	  case ReduceType::kAbsSum:
51	    return make_zero(dst->dtype);
52	  case ReduceType::kMax:
53	    return make_const(dst->dtype, -INFINITY);
54	  case ReduceType::kMin:
55	    return make_const(dst->dtype, INFINITY);
56	  case ReduceType::kAbsMax:
57	    return make_const(dst->dtype, 0);
58	  default:
59	    ICHECK(0);
60	  }
61	}
62	
63	PrimExpr ReduceOp::MakeReduce(const PrimExpr &a, const PrimExpr &b) const {
64	  PrimExpr lhs = a, rhs = b;
65	  if (lhs->dtype != rhs->dtype) {
66	    rhs = Cast(lhs->dtype, rhs);
67	  }
68	  switch (type) {
69	  case ReduceType::kSum:
70	    return lhs + rhs;
71	  case ReduceType::kAbsSum:
72	    return lhs + Max(rhs, -rhs);
73	  case ReduceType::kMax:
74	    return Max(lhs, rhs);
75	  case ReduceType::kMin:
76	    return Min(lhs, rhs);
77	  case ReduceType::kAbsMax:
78	    return Max(Max(lhs, rhs), -Min(lhs, rhs));
79	  default:
80	    ICHECK(0);
81	    return PrimExpr(0);
82	  }
83	}
84	
85	std::string ReduceOp::MakeCodegenReducer() const {
86	  switch (type) {
87	  case ReduceType::kSum:
88	    return "tl::SumOp";
89	  case ReduceType::kAbsSum:
90	    return "tl::SumOp";
91	  case ReduceType::kMax:
92	    return "tl::MaxOp";
93	  case ReduceType::kMin:
94	    return "tl::MinOp";
95	  case ReduceType::kAbsMax:
96	    return "tl::MaxOp";
97	  default:
98	    ICHECK(0);
99	    return "";
100	  }
101	}
102	
103	Stmt ReduceOp::Lower(const LowerArgs &T, arith::Analyzer *analyzer) const {
104	  ICHECK(this->src.scope() == "local.fragment" &&
105	         this->dst.scope() == "local.fragment")
106	      << "Reduce for shared memory not implemented.";
107	  auto src_buffer = T.buffer_remap[this->src];
108	  auto dst_buffer = T.buffer_remap[this->dst];
109	  Fragment src_layout = T.layout_map[this->src].as<Fragment>().value();
110	  Fragment dst_layout = T.layout_map[this->dst].as<Fragment>().value();
111	  size_t src_dim = src_layout->InputDim();
112	  size_t dst_dim = dst_layout->InputDim();
113	
114	  bool is_1d_reduce = src_dim == dst_dim && dst_dim == 1;
115	
116	  if (is_1d_reduce) {
117	    ICHECK(is_one(dst_layout->OutputShape().back()))
118	        << "Reduce for scalar not implemented.";
119	  } else {
120	    ICHECK(src_dim == dst_dim + 1) << "Reduce dimension mismatch.";
121	  }
122	
123	  Array<IterVar> dst_vars;
124	  for (size_t i = 0; i < dst_dim; i++) {
125	    Var var = Var(std::string{char('i' + i)});
126	    dst_vars.push_back(IterVar(Range(0, dst_layout->InputShape()[i]), var,
127	                               IterVarType::kDataPar));
128	  }
129	  Array<IterVar> src_vars;
130	  if (!is_1d_reduce) {
131	    src_vars = dst_vars;
132	  }
133	  src_vars.insert(src_vars.begin() + this->dim,
134	                  {Range(0, src_layout->InputShape()[this->dim]), Var("rv"),
135	                   IterVarType::kDataPar});
136	  Array<PrimExpr> src_indices = src_layout->Forward(
137	      src_vars.Map([](const auto &iv) { return PrimExpr(iv->var); }));
138	  Array<PrimExpr> dst_indices = dst_layout->Forward(
139	      dst_vars.Map([](const auto &iv) { return PrimExpr(iv->var); }));
140	
141	  Array<Stmt> stmts;
142	
143	  bool require_init = this->clear;
144	  // sum op must be cleared
145	  if (this->type == ReduceType::kSum) {
146	    require_init = true;
147	  } else if (this->type == ReduceType::kAbsSum) {
148	    require_init = true;
149	  }
150	
151	  Buffer clear_buffer = dst_buffer;
152	  bool need_duplicate = false;
153	  if (this->type == ReduceType::kSum && !this->clear) {
154	    need_duplicate = true;
155	  } else if (this->type == ReduceType::kAbsSum && !this->clear) {
156	    need_duplicate = true;
157	  }
158	
159	  if (need_duplicate) {
160	    // Create a new buffer with same shape and dtype as dst_buffer
161	    clear_buffer = decl_buffer(dst_buffer->shape, dst_buffer->dtype,
162	                               dst_buffer->name + "_clear",
163	                               GetPtrStorageScope(dst_buffer->data));
164	  }
165	
166	  // make reduce-init stmt
167	  if (require_init)
168	    stmts.push_back(
169	        BufferStore(clear_buffer, this->MakeInitValue(), dst_indices));
170	
171	  // make thread-local reduce
172	  Array<PrimExpr> src_indice_compressed;
173	  Array<IterVar> src_var_compressed;
174	  for (size_t i = 0; i < src_layout->OutputDim(); i++) {
175	    PrimExpr expr;
176	    IterVar var;
177	    std::tie(expr, var) = CompressIterator(src_indices[i], src_vars,
178	                                           src_vars[this->dim]->var, analyzer);
179	    src_indice_compressed.push_back(expr);
180	    src_var_compressed.push_back(var);
181	  }
182	  Stmt reduce_local = BufferStore(
183	      clear_buffer,
184	      this->MakeReduce(BufferLoad(clear_buffer, dst_indices),
185	                       BufferLoad(src_buffer, src_indice_compressed)),
186	      dst_indices);
187	  for (int i = src_layout->OutputDim() - 1; i >= 0; i--) {
188	    reduce_local =
189	        For(src_var_compressed[i]->var, 0, src_var_compressed[i]->dom->extent,
190	            ForKind::kUnrolled, reduce_local, NullOpt,
191	            {{tir::attr::pragma_unroll_explicit, Bool(false)}});
192	  }
193	  stmts.push_back(reduce_local);
194	
195	  // make inter-thread reduce
196	  PrimExpr src_thread = src_layout->ForwardThread(
197	      src_vars.Map([](const auto &iv) { return PrimExpr(iv->var); }), {});
198	  auto iter_sum =
199	      arith::NormalizeToIterSum(src_thread, ToVMap(src_vars), analyzer);
200	  for (const auto &iter_split : iter_sum->args) {
201	    auto mark = iter_split->source->source.as<Var>();
202	    ICHECK(mark.defined());
203	    if (mark.value().same_as(src_vars[this->dim]->var)) {
204	      auto scale = as_const_int(iter_split->scale);
205	      auto extent = as_const_int(iter_split->extent);
206	      ICHECK(scale != nullptr && extent != nullptr);
207	      if (*extent == 1)
208	        continue;
209	      int reducing_threads = (*extent) * (*scale);
210	      std::stringstream ss;
211	
212	      bool has_arch = T.target->attrs.count("arch") > 0;
213	      if (has_arch && Downcast<String>(T.target->attrs["arch"]) == "sm_90") {
214	        ss << "tl::AllReduce<" << this->MakeCodegenReducer() << ", "
215	           << reducing_threads << ", " << (*scale) << ">::run_hopper";
216	      } else {
217	        ss << "tl::AllReduce<" << this->MakeCodegenReducer() << ", "
218	           << reducing_threads << ", " << (*scale) << ">::run";
219	      }
220	      Array<PrimExpr> thread_reduce_args = {
221	          StringImm(ss.str()), BufferLoad(clear_buffer, dst_indices)};
222	      if (reducing_threads >= 32) {
223	        PrimExpr workspace = T.AddWorkspace(
224	            *as_const_int(T.thread_bounds->extent), clear_buffer->dtype);
225	        thread_reduce_args.push_back(workspace);
226	      }
227	      auto call =
228	          Call(clear_buffer->dtype, builtin::call_extern(), thread_reduce_args);
229	      stmts.push_back(BufferStore(clear_buffer, call, dst_indices));
230	    }
231	  }
232	  Stmt reduce_interthread = BufferStore(
233	      clear_buffer, BufferLoad(clear_buffer, dst_indices), dst_indices);
234	
235	  // copy clear_buffer to dst_buffer
236	  if (need_duplicate) {
237	    // if is reduce sum, we should add a copy from clear_buffer to dst_buffer
238	    if (this->type == ReduceType::kSum) {
239	      stmts.push_back(BufferStore(dst_buffer,
240	                                  Add(BufferLoad(dst_buffer, dst_indices),
241	                                      BufferLoad(clear_buffer, dst_indices)),
242	                                  dst_indices));
243	    } else if (this->type == ReduceType::kAbsSum) {
244	      stmts.push_back(BufferStore(dst_buffer,
245	                                  Add(BufferLoad(dst_buffer, dst_indices),
246	                                      BufferLoad(clear_buffer, dst_indices)),
247	                                  dst_indices));
248	    } else {
249	      ICHECK(false) << "Unsupported reduce type: " << (int)this->type;
250	    }
251	  }
252	  // make the outer spatial loop
253	  Stmt body = stmts.size() > 1 ? SeqStmt(stmts) : stmts[0];
254	  for (int i = dst_layout->InputDim() - 1; i >= 0; i--) {
255	    body = For(dst_vars[i]->var, 0, dst_vars[i]->dom->extent,
256	               ForKind::kParallel, body);
257	  }
258	
259	  body = PartitionLoop(Downcast<For>(body), T.thread_var, analyzer, dst_layout);
260	  if (need_duplicate) {
261	    body = Allocate(clear_buffer->data, clear_buffer->dtype,
262	                    clear_buffer->shape, const_true(), body);
263	  }
264	  return body;
265	}
266	
267	LayoutMap ReduceOp::InferLayout(const LayoutInferArgs &T, InferLevel level) {
268	  if (level >= InferLevel::kStrict)
269	    return {};
270	  if (src.scope() == "local.fragment" && dst.scope() == "local.fragment" &&
271	      T.layout_map.count(src) && !T.layout_map.count(dst)) {
272	    auto src_layout = T.layout_map[src].as<Fragment>().value();
273	
274	    PrimExpr indice_rep_extent = src->shape[dim];
275	    PrimExpr src_rep_extent = src_layout->ReplicateExtent();
276	    PrimExpr dest_buffer_rep_extent = indice_rep_extent * src_rep_extent;
277	
278	    Array<PrimExpr> fwd;
279	    for (int i = 0; i < static_cast<int>(src->shape.size()); i++) {
280	      if (i == dim) {
281	        fwd.push_back(FloorMod(ReplicationPlaceholder(), indice_rep_extent));
282	      } else if (i < dim) {
283	        fwd.push_back(InputPlaceholder(i));
284	      } else if (i > dim) {
285	        fwd.push_back(InputPlaceholder(i - 1));
286	      }
287	    }
288	    auto thd = src_layout->ForwardThread(
289	        fwd, FloorDiv(ReplicationPlaceholder(), indice_rep_extent));
290	    Fragment dst_layout =
291	        Fragment(dst->shape, {}, thd, dest_buffer_rep_extent, NullOpt)
292	            ->CondenseReplicateVar()
293	            ->BindThreadRange(T.thread_bounds);
294	    return {{dst, dst_layout}};
295	  }
296	  return {};
297	}
