450	// template <typename T, uint32_t Len>
451	// CATLASS_DEVICE void fill(LocalTensor<T> const &ubOut, T value) {
452	//   AscendC::Duplicate(ubOut, value, Len);
453	// }
454	
455	template <typename T>
456	CATLASS_DEVICE void
457	reduce_sum_half(LocalTensor<T> const &dstTensor,
458	                LocalTensor<T> const &srcTensor, const int32_t mask,
459	                const int32_t repeatTime, const int32_t srcRepStride) {
460	  AscendC::WholeReduceSum<T>(dstTensor, srcTensor, mask, repeatTime, 1, 1,
461	                             srcRepStride);
462	}
463	
464	// Row-reduce a narrow column range of a wider tile.
465	//
466	// AscendC's Reduce* takes a {M, N} shape and reads the source as a CONTIGUOUS
467	// M x N block, so it cannot express "N columns out of each row of a wider
468	// buffer": for a [M, 512] tile and a logical width of 64 it reads elements
469	// [0, M*64), which is row 0's first eight chunks, not the first 64 columns of
470	// each of the M rows. WholeReduce* instead takes an explicit per-repeat source
471	// stride, so one repeat per row with srcRepStride set to the PHYSICAL row width
472	// reduces the intended region. One repeat covers at most 256 bytes, which is
473	// what bounds the usable width.
474	template <typename T>
475	CATLASS_DEVICE void
