                  const int32_t repeatTime, const int32_t srcRepStride) {
  AscendC::WholeReduceMin<T>(dstTensor, srcTensor, mask, repeatTime, 1, 1,
                             srcRepStride,
                             AscendC::ReduceOrder::ORDER_ONLY_VALUE);
}

